def generate(model, prompt, L=8, N=4):
    x = prompt + [MASK] * L
    resp = range(len(prompt), len(prompt) + L)
    for step in range(1, N + 1):
        t = 1 - (step - 1) / N
        s = t - 1 / N
        probs = model(x).softmax(-1)      # one pass, all positions
        pred, conf = probs.argmax(-1), probs.max(-1)
        for i in resp:
            if x[i] != MASK:
                pred[i], conf[i] = x[i], 1.0   # carry over
        n_un = floor(L * (1 - s))
        keep = top_k(resp, conf, n_un)
        for i in resp:
            x[i] = pred[i] if i in keep else MASK
    return x[len(prompt):]
